function renderTemplateInputs(){const selectValue=document.querySelector('#templateSelect').value,selected=selectValue.startsWith('external:')?selectedExternalTemplate:installerTemplates.find(t=>t.file===selectValue),summary=document.querySelector('#templateSummary'),inputs=document.querySelector('#templateInputs');if(!selected){summary.textContent='';inputs.innerHTML='';document.querySelector('#templateForm button[type=submit]').disabled=true;return}summary.innerHTML=`<b>${escapeHtml(selected.name)}</b><small>${escapeHtml(selected.repository)}</small><p>${escapeHtml(selected.overview||'No overview provided.')}</p>`;const unsupported=selected.configs.filter(c=>!['port','path','variable'].includes(c.type.toLowerCase()));inputs.innerHTML=selected.configs.map((c,i)=>{const type=c.type.toLowerCase();if(type==='path')return `<div class="volume-setting"><b>${escapeHtml(c.name)}</b><small>Container folder: ${escapeHtml(c.target)}</small><label>Storage type<select data-volume-mode="${i}"><option value="volume" selected>Isolated Docker volume (recommended)</option><option value="bind">Bind mount a host folder</option></select></label><label class="bind-path" hidden>Host folder path<input type="text" data-bind-source="${i}" placeholder="/path/to/folder on this computer" autocomplete="off"></label><small class="volume-help">Isolated storage is separate from host files. Bind mounts expose the selected host folder to this container.</small></div>`;if(type==='port')return `<label>${escapeHtml(c.name)} · container port ${escapeHtml(c.target)}<input type="number" min="1" max="65535" data-config="${i}" value="${escapeHtml(c.default)}" ${c.required?'required':''} placeholder="Host port"></label>`;if(type==='variable'){const commonValues=getCommonInstallVariables(),value=Object.prototype.hasOwnProperty.call(commonValues,c.name)?commonValues[c.name]:c.default;return `<label>${escapeHtml(c.name)}${c.required?' · required':''}<input type="${c.mask?'password':'text'}" data-config="${i}" value="${escapeHtml(value)}" ${c.required?'required':''} autocomplete="off" placeholder="${c.mask?'Enter secret value':'Optional'}"></label>`}return ''}).join('')+(unsupported.length?`<div class="unsupported-setting">Unsupported setting(s): ${unsupported.map(c=>escapeHtml(c.name)+' ('+escapeHtml(c.type)+')').join(', ')}. The template cannot be installed with this version.</div>`:'');inputs.querySelectorAll('[data-volume-mode]').forEach(mode=>mode.addEventListener('change',()=>{const path=inputs.querySelector(`[data-bind-source="${mode.dataset.volumeMode}"]`),label=path.closest('.bind-path');label.hidden=mode.value!=='bind';path.required=mode.value==='bind'}));document.querySelector('#templateForm button[type=submit]').disabled=unsupported.length>0;document.querySelector('#templateName').value=`ca-${selected.name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,30)||'app'}-test`}
function renderCatalog(data){if(!data.connected){document.querySelector('#shimRepoName').textContent='No repository connected';document.querySelector('#shimProfile').textContent='Connect a local repository to preview its CA entries.';document.querySelector('#shimApps').innerHTML='<div class="shim-empty">Connect a repository folder to build a local catalog.</div>';document.querySelector('#shimPlugins').innerHTML='';return}const profile=data.repository.profile||{};document.querySelector('#shimRepoName').textContent=data.repository.name;document.querySelector('#shimProfile').textContent=profile.Profile||'No repository profile description.';const apps=document.querySelector('#shimApps'),plugins=document.querySelector('#shimPlugins');apps.innerHTML=data.apps.length?data.apps.map(t=>`<article class="ca-card"><div class="ca-card-top"><span class="ca-type">DOCKER APP</span><span class="pill ${t.ok?'good':'pending'}">${t.ok?'READY':'NEEDS WORK'}</span></div><h3>${escapeHtml(t.name||'Unnamed template')}</h3><p>${escapeHtml(t.overview||'No overview in template XML.')}</p><small class="ca-image">${escapeHtml(t.repository||'Image reference missing')}</small><small class="ca-file">${escapeHtml(t.file)}</small>${t.errors.map(e=>`<small class="error-text">${escapeHtml(e)}</small>`).join('')}<button class="primary small" data-install-template="${escapeHtml(t.file)}" ${t.ok?'':'disabled'}>${t.ok?'Edit template':'Edit'}</button></article>`).join(''):'<div class="shim-empty">No Docker templates were found in this repository.</div>';plugins.innerHTML=data.plugins.length?data.plugins.map(t=>`<article class="ca-card plugin-card"><div class="ca-card-top"><span class="ca-type">UNRAID PLUGIN</span><span class="pill pending">HOST REQUIRED</span></div><h3>${escapeHtml(t.name||'Unnamed plugin')}</h3><p>${escapeHtml(t.overview||'No overview in wrapper XML.')}</p><small class="ca-image">Manifest: ${escapeHtml(t.plugin_url||'PluginURL missing')}</small><small class="ca-file">${escapeHtml(t.file)}</small>${t.errors.map(e=>`<small class="error-text">${escapeHtml(e)}</small>`).join('')}<button class="outline" data-plugin-info="${escapeHtml(t.file)}">Why no local install?</button></article>`).join(''):'<div class="shim-empty">No plugin wrappers were found in this repository.</div>';apps.querySelectorAll('[data-install-template]').forEach(b=>b.addEventListener('click',()=>selectTemplateInSandbox(b.dataset.installTemplate)));plugins.querySelectorAll('[data-plugin-info]').forEach(b=>b.addEventListener('click',()=>toast('Plugin install hooks target Unraid paths and services. The shim only emulates the catalog and Docker template installer.')))}
async function loadCatalog(search=''){try{renderCatalog(await api(`/api/ca/catalog${search?`?q=${encodeURIComponent(search)}`:''}`))}catch(e){toast(e.message)}}
async function selectTemplateInSandbox(file){await navigate('template-editor');document.querySelector('#templateEditorSelect').value=file;await loadTemplateEditorFile(file)}
let searchTimer;document.querySelector('#catalogSearch').addEventListener('input',e=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>loadCatalog(e.target.value),180)});
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function loadCABrowser(){try{await loadCACategories();if(!caObserver){caObserver=new IntersectionObserver(entries=>{if(entries.some(entry=>entry.isIntersecting)&&caPage*12<caTotal)fetchCABrowser().catch(error=>toast(error.message))},{rootMargin:'650px 0px'});caObserver.observe(document.querySelector('#caScrollSentinel'))}await fetchCABrowser(true)}catch(e){document.querySelector('#caResults').innerHTML=`<div class="shim-empty">${escapeHtml(e.message)}. The CA portal may be temporarily unavailable.</div>`;document.querySelector('#caResultSummary').textContent='Catalog unavailable';document.querySelector('#caScrollStatus').textContent=''}}
async function loadCACategories(){const select=document.querySelector('#caCategory');if(select.dataset.loaded)return;const data=await api('/api/ca/categories');select.innerHTML='<option value="all">All categories</option>'+(data.categories||[]).map(c=>`<option value="${escapeHtml(c.path)}">${escapeHtml(c.name)} (${Number(c.count)||0})</option>`).join('');select.dataset.loaded='true'}
async function fetchCABrowser(reset=false){if(reset){caBrowserRequest++;caPage=0;caTotal=0;caLoading=false;document.querySelector('#caResults').replaceChildren();document.querySelector('#caScrollStatus').textContent='Loading…';document.querySelector('#caScrollSentinel').hidden=false}if(caLoading||caPage*12>=caTotal&&caPage>0)return;caLoading=true;const requestId=caBrowserRequest,page=caPage,params=new URLSearchParams({q:document.querySelector('#caSearch').value.trim(),category:document.querySelector('#caCategory').value,type:document.querySelector('#caType').value,sort:document.querySelector('#caSort').value,page:String(page),limit:'12'});try{const data=await api(`/api/ca/browse?${params}`);if(requestId!==caBrowserRequest)return;caTotal=Number(data.total)||0;const hits=data.hits||[],results=document.querySelector('#caResults'),sentinel=document.querySelector('#caScrollSentinel');if(hits.length){results.insertAdjacentHTML('beforeend',hits.map(caCard).join(''));caPage=page+1}else if(page===0)results.innerHTML='<div class="shim-empty">No matching Community Apps entries. Try another search or category.</div>';const loaded=results.querySelectorAll('.ca-market-card').length;document.querySelector('#caResultSummary').textContent=`${loaded.toLocaleString()} of ${caTotal.toLocaleString()} catalog entries`;const hasMore=loaded<caTotal&&hits.length>0;sentinel.hidden=!hasMore;sentinel.textContent=hasMore?'Scroll to load more entries':'You’re all caught up';document.querySelector('#caScrollStatus').textContent=hasMore?'More apps load as you scroll':'End of results'}catch(error){if(requestId===caBrowserRequest)throw error}finally{if(requestId===caBrowserRequest){caLoading=false;const sentinel=document.querySelector('#caScrollSentinel');if(!sentinel.hidden&&sentinel.getBoundingClientRect().top<window.innerHeight+650&&caPage*12<caTotal)requestAnimationFrame(()=>fetchCABrowser().catch(error=>toast(error.message)))}}}

function caCard(item){const plugin=item.appType==='plugin',url=item.InstallTemplateURL||item.TemplateURL||'',cats=(item.CategoryList||[]).slice(0,2).join(' · '),portal=`https://ca.unraid.net/apps?q=${encodeURIComponent(item.Name)}`,image=item.Icon||'';return `<article class="ca-market-card"><div class="ca-market-top">${image?`<img src="${escapeHtml(image)}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.hidden=true">`:'<span class="ca-market-placeholder">CA</span>'}<div><span class="ca-type">${plugin?'PLUGIN':'DOCKER APP'}</span>${item.isOfficial?'<span class="ca-official">OFFICIAL</span>':''}</div></div><h2>${escapeHtml(item.Name)}</h2><p>${escapeHtml(item.overviewPreview||item.Overview||'No overview provided.')}</p><div class="ca-market-meta">${escapeHtml(cats||'Community Apps')} ${item.beta?'<span>Beta</span>':''} ${item.deprecated?'<span>Deprecated</span>':''}</div><div class="ca-market-actions">${plugin?`${runtime.unraid&&item.PluginURL?`<button class="primary small" data-ca-plugin-install="${escapeHtml(item.PluginURL)}">Install plugin</button>`:''}<a class="outline" href="${portal}" target="_blank" rel="noreferrer">View on CA ↗</a>`:url?`<button class="primary small" data-ca-install="${escapeHtml(url)}">Review &amp; install</button><a class="market-link" href="${portal}" target="_blank" rel="noreferrer">CA listing ↗</a>`:`<a class="outline" href="${portal}" target="_blank" rel="noreferrer">View on CA ↗</a>`}</div></article>`}
async function selectCATemplate(url){try{const template=await api(`/api/ca/template?url=${encodeURIComponent(url)}`);if(!template.ok){toast((template.errors||['Template is incomplete.']).join(' '));return}selectedExternalTemplate=template;const select=document.querySelector('#templateSelect');select.innerHTML=`<option value="external:${escapeHtml(url)}">CA Store · ${escapeHtml(template.name)}</option>`;select.value=`external:${url}`;renderTemplateInputs();document.querySelector('#storeInstaller').hidden=false;document.querySelector('#storeInstallerBackdrop').hidden=false;document.body.classList.add('drawer-open');document.querySelector('#closeStoreInstaller').focus();toast('Review the CA template settings before installing.')}catch(e){toast(e.message)}}
function closeStoreInstaller(){document.querySelector('#storeInstaller').hidden=true;document.querySelector('#storeInstallerBackdrop').hidden=true;document.body.classList.remove('drawer-open')}
document.querySelector('#closeStoreInstaller').addEventListener('click',closeStoreInstaller);document.querySelector('#storeInstallerBackdrop').addEventListener('click',closeStoreInstaller);document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!document.querySelector('#storeInstaller').hidden)closeStoreInstaller()});
function resetCABrowser(){fetchCABrowser(true).catch(error=>toast(error.message))}
document.querySelector('#caResults').addEventListener('click',async event=>{const pluginButton=event.target.closest('[data-ca-plugin-install]');if(pluginButton){const url=pluginButton.dataset.caPluginInstall;if(!runtime.unraid){toast('Plugin installation requires CA Workshop to run on the Unraid host.');return}if(!confirm(`Install this plugin on the Unraid server with its plugin manager?\n\n${url}`))return;pluginButton.disabled=true;pluginButton.textContent='Installing…';try{await api('/api/unraid/plugins/install',{method:'POST',body:JSON.stringify({url,confirmed:true})});toast('Plugin installed. Refresh the Unraid page to load its settings.');await loadRuntime()}catch(error){toast(error.message)}finally{pluginButton.disabled=false;pluginButton.textContent='Install plugin'}return}const button=event.target.closest('[data-ca-install]');if(button)selectCATemplate(button.dataset.caInstall)});
document.querySelector('#shimApps').addEventListener('click',async event=>{const button=event.target.closest('[data-install-template]');if(!button)return;const file=button.dataset.installTemplate;if(!file)return;if(!confirm('Install locally (Docker sandbox) or on Unraid server? Click OK for server, Cancel for local.')){await selectTemplateInSandbox(file);return}try{const unraidStatus=await api('/api/unraid/status');if(unraidStatus.connected){await api('/api/unraid/docker/run',{method:'POST',body:JSON.stringify({template:file})});toast('App installation started on Unraid server.')}else{toast('Unraid server not connected; installing locally.');await selectTemplateInSandbox(file)}}catch(e){toast('Server install failed: '+e.message);await selectTemplateInSandbox(file)}});
document.querySelector('#caSearchForm').addEventListener('submit',event=>{event.preventDefault();resetCABrowser()});document.querySelector('#caSearch').addEventListener('input',()=>{clearTimeout(caTimer);caTimer=setTimeout(resetCABrowser,300)});['caCategory','caType','caSort'].forEach(id=>document.querySelector(`#${id}`).addEventListener('change',resetCABrowser));document.querySelector('#popularPlugins').addEventListener('click',()=>{document.querySelector('#caType').value='plugin';document.querySelector('#caSort').value='popularity';document.querySelector('#caCategory').value='all';resetCABrowser()});

async function refreshRepo(){try{const d=await api('/api/repo/validate',{method:'POST',body:'{}'});drawRepo(d)}catch(e){toast(e.message)}}
async function connectRepo(){const path=window.prompt('Enter the full path to your local repository folder:');if(!path)return;try{drawRepo(await api('/api/repo/connect',{method:'POST',body:JSON.stringify({path})}));toast('Repository folder connected.')}catch(e){toast(e.message)}}
document.querySelector('#bootstrapForm').addEventListener('submit',async ev=>{ev.preventDefault();const form=ev.currentTarget,button=form.querySelector('button[type=submit]'),status=document.querySelector('#bootstrapStatus'),payload=Object.fromEntries(new FormData(form).entries());button.disabled=true;button.textContent='Creating GitHub repository…';status.textContent='Authorizing and generating the starter repository…';try{const result=await api('/api/repo/bootstrap',{method:'POST',body:JSON.stringify(payload)});drawRepo(result);status.innerHTML=`Created <a href="${escapeHtml(result.github_url)}" target="_blank" rel="noreferrer">${escapeHtml(result.github_url)}</a> and cloned it to ${escapeHtml(result.path)}.`;document.querySelector('#githubToken').value='';form.reset();document.querySelector('#bootstrapCard').open=false;await loadActivity();toast('Starter repository created and connected.')}catch(e){status.textContent=e.message;toast(e.message)}finally{document.querySelector('#githubToken').value='';button.disabled=false;button.textContent='Create & clone starter repository'}});
document.querySelector('#populateForm').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,file=document.querySelector('#populateIcon').files[0],status=document.querySelector('#populateStatus'),button=form.querySelector('button[type=submit]');if(!file){status.textContent='Choose an app icon first.';return}if(file.size>2_000_000){status.textContent='Choose an image smaller than 2 MB.';return}button.disabled=true;status.textContent='Creating the profile, template, and icon in your local repository…';try{const iconData=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('The selected icon could not be read.'));reader.readAsDataURL(file)}),values=Object.fromEntries(new FormData(form).entries()),payload={...values,icon:{type:file.type,data:iconData},remove_plugin_example:form.elements.removePluginExample.checked};const result=await api('/api/repo/populate',{method:'POST',body:JSON.stringify(payload)});drawRepo(result);status.textContent=`Saved ${result.created_files.join(', ')} to the connected folder. Review the files, then validate them.`;await loadActivity();toast('Example app files saved locally.');if(confirm('The example files are saved. Run the repository preflight now?'))await refreshRepo()}catch(error){status.textContent=error.message;toast(error.message)}finally{button.disabled=false}});document.querySelector('#readyValidate').addEventListener('click',async()=>{await refreshRepo();navigate('applications')});
function isApplicationAsset(path){return /^(templates|plugins|images)\//i.test(path)||/(^|\/)icon\.(png|jpe?g|webp|svg)$/i.test(path)}
function repositorySupportFiles(files){return files.filter(file=>!isApplicationAsset(file))}
function repoFileRow(file,attribute){const saved=savedRepoFiles.has(file);return `<button class="file-row repo-file" ${attribute}="${escapeHtml(file)}"><span class="file-icon ${saved?'saved':file.endsWith('.xml')?'xml':'plain'}">${saved?'✓':file.endsWith('.xml')?'〈〉':'≡'}</span><span><b>${escapeHtml(file)}</b><small>${saved?'Saved locally':'Repository setup file'}</small></span><span class="file-state ${saved?'ok':''}">${saved?'✓ Saved':'Edit'}</span></button>`}
async function loadRepoFiles(){try{const d=await api('/api/repo/files'),box=document.querySelector('#repoFileList'),allFiles=new Set(d.files||[]);let pruned=false;for(const file of savedRepoFiles)if(!allFiles.has(file)){savedRepoFiles.delete(file);pruned=true}if(pruned)persistSavedRepoFiles();const files=repositorySupportFiles(d.files||[]);box.innerHTML=files.length?files.slice(0,6).map(f=>repoFileRow(f,'data-repo-file')).join(''):`<div class="history-empty">No repository setup files found. App templates and icons are managed in Applications.</div>`}catch(e){toast(e.message)}}
const submissionOptions=['Draft','Submitted','In review','Changes requested','Approved','Published'];
let serverSubmissionStatuses={};
function submissionStorageKey(){return `ca-workshop-submissions:${repo?.path||'no-repository'}`}
function getSubmissionStatuses(){try{const local=JSON.parse(localStorage.getItem(submissionStorageKey())||'{}');return {...local,...serverSubmissionStatuses}}catch{return serverSubmissionStatuses}}
async function setSubmissionStatus(file,status){const values=getSubmissionStatuses();values[file]=status;serverSubmissionStatuses[file]=status;try{localStorage.setItem(submissionStorageKey(),JSON.stringify(values))}catch{}try{await api('/api/submissions/status',{method:'POST',body:JSON.stringify({file,status})})}catch(e){}}
async function syncSubmissionStatuses(){try{const res=await api('/api/submissions/status');if(res&&res.statuses){serverSubmissionStatuses=res.statuses;try{const local=JSON.parse(localStorage.getItem(submissionStorageKey())||'{}');localStorage.setItem(submissionStorageKey(),JSON.stringify({...local,...res.statuses}))}catch{}}}catch{}}
function appMetric(value,format=value=>value){return value===undefined||value===null||value===''?'Unavailable':escapeHtml(format(value))}
async function loadApplicationStats(file,name,container,type='docker'){container.textContent='Checking the CA Store…';try{const result=await api(`/api/ca/browse?q=${encodeURIComponent(name)}&type=${encodeURIComponent(type)}&page=0&limit=8`),hit=(result.hits||[]).find(item=>String(item.Name||'').trim().toLowerCase()===name.trim().toLowerCase());if(!hit){container.textContent='No exact name match found in the CA Store. Check the app name or search the CA Store manually.';return}const categories=hit.CategoryList||hit.categoryPaths||[],cats=Array.isArray(categories)?categories.join(', '):String(categories),repository=hit.Repo||hit.Project||'';container.innerHTML=`<div class="application-metrics-grid"><div><small>Application type</small><b>${appMetric(hit.appType)}</b></div><div><small>Categories</small><b>${appMetric(cats)}</b></div><div><small>Added</small><b>${appMetric(hit.DateAdded??hit.dateAdded)}</b></div><div><small>Last update</small><b>${appMetric(hit.LastUpdate??hit.lastUpdate)}</b></div><div><small>GitHub stars</small><b>${appMetric(hit.githubStars??hit.GitHubStars)}</b></div><div><small>CA downloads</small><b>${appMetric(hit.downloads,value=>Number(value).toLocaleString())}</b></div><div><small>Repository / image</small><b>${appMetric(repository)}</b></div><div><small>Docker Hub stars</small><b>${appMetric(hit.dockerHubStars??hit.DockerHubStars)}</b></div></div><small class="metrics-source">Matched by exact app name in the Community Apps catalog. Unavailable fields are not provided by the catalog result.</small>`}catch(error){container.textContent=`Could not load CA Store metrics: ${error.message}`}}
function applicationRow(item,index,{stats=false}={}){const status=getSubmissionStatuses()[item.file]||'Draft',schema=item.schema_validation;return `<article class="application-row"><div class="application-icon">${escapeHtml((item.name||'App').slice(0,2).toUpperCase())}</div><div class="application-main"><b>${escapeHtml(item.name||item.file)}</b><small>${escapeHtml(item.file)}</small><div class="application-meta"><span class="pill ${item.ok?'good':'pending'}">${item.ok?'VALID':'FIX REQUIRED'}</span><span class="application-status">Submission: ${escapeHtml(status)}</span></div>${schema?`<div class="application-schema ${schema.status==='invalid'?'invalid':''}">XSD ${escapeHtml(schema.status)} · ${escapeHtml(schema.message||'')}</div>`:''}${item.errors?.length?`<ul class="application-errors">${item.errors.map(error=>`<li>${escapeHtml(error)}</li>`).join('')}</ul>`:'<div class="application-valid-note">Template validation passed. Ready for CA submission.</div>'}${stats?`<div class="application-metrics-content" data-app-metrics="${index}">Load statistics from the CA Store.</div><button type="button" class="outline" data-app-stats="${index}">Load statistics</button>`:''}</div><div class="application-actions"><button class="outline" type="button" data-app-edit="${escapeHtml(item.file)}">${item.ok?'Edit template':'Edit'}</button>${stats?'':`<button class="outline" type="button" data-app-icons="${escapeHtml(item.file)}">Icon</button>`}</div></article>`}
async function loadApplications(){const box=document.querySelector('#applicationList');try{await syncSubmissionStatuses();const data=await api('/api/status');repo=data.repo;const templates=(data.repo?.templates||[]).filter(item=>item.kind==='docker'||(item.kind==='unknown'&&item.file?.startsWith('templates/')));document.querySelector('#applicationCount').textContent=data.repo?.connected?templates.length:'—';document.querySelector('#applicationReadyCount').textContent=data.repo?.connected?templates.filter(item=>item.ok).length:'—';const statuses=templates.map(item=>getSubmissionStatuses()[item.file]||'Draft');document.querySelector('#applicationSubmissionState').textContent=data.repo?.connected?statuses.filter(status=>['Submitted','In review','Changes requested','Approved','Published'].includes(status)).length:'—';document.querySelector('#applicationMetricsState').textContent=data.repo?.connected?statuses.filter(status=>status==='Published').length:'—';if(!data.repo?.connected){box.innerHTML='<div class="history-empty">Connect a repository on the Repository page to manage applications.</div>';return}if(!templates.length){box.innerHTML='<div class="history-empty">No Docker templates yet. Convert a Compose file or create one from the dummy template.</div>';return}box.innerHTML=templates.map((item,index)=>applicationRow(item,index)).join('');box.dataset.applicationFiles=JSON.stringify(templates.map(item=>({file:item.file,name:item.name||item.file}))) }catch(error){box.innerHTML=`<div class="history-empty">${escapeHtml(error.message)}</div>`}}
async function loadSubmissionTracker(){const box=document.querySelector('#submissionTracker');try{await syncSubmissionStatuses();const data=await api('/api/status');repo=data.repo;if(!data.repo?.connected){box.innerHTML='<div class="history-empty">Connect a repository to track app and plugin submissions.</div>';return}const items=(data.repo.templates||[]).filter(item=>item.kind==='docker'||item.kind==='plugin'||(item.kind==='unknown'&&(/^(templates|plugins)\//.test(item.file||'')))),statuses=getSubmissionStatuses();box.innerHTML=items.length?items.map(item=>{const isPlugin=item.kind==='plugin'||item.file?.startsWith('plugins/'),type=isPlugin?'Plugin':'Docker app';return `<div class="submission-row"><div><b>${escapeHtml(item.name||item.file)} <span class="submission-kind">${type}</span></b><small>${escapeHtml(item.file)} · ${item.ok?'Local validation passed':'Fix local validation issues before submitting'}</small></div><label>Portal status<select data-submission-status="${escapeHtml(item.file)}">${submissionOptions.map(status=>`<option ${status===(statuses[item.file]||'Draft')?'selected':''}>${status}</option>`).join('')}</select></label>${isPlugin?`<button class="outline" type="button" data-submission-file="${escapeHtml(item.file)}">View file</button>`:`<button class="outline" type="button" data-app-edit="${escapeHtml(item.file)}">${item.ok?'Edit':'Fix'}</button>`}</div>`}).join(''):'<div class="history-empty">No Docker applications or plugin wrappers found in this repository.</div>'}catch(error){box.textContent=error.message}}
async function loadPublishedStats(){const box=document.querySelector('#publishedApplicationStats');try{const data=await api('/api/status');repo=data.repo;const published=(data.repo?.templates||[]).filter(item=>item.kind==='docker'&&getSubmissionStatuses()[item.file]==='Published');box.dataset.applicationFiles=JSON.stringify(published.map(item=>({file:item.file,name:item.name||item.file})));box.innerHTML=published.length?published.map((item,index)=>applicationRow(item,index,{stats:true})).join(''):'<div class="history-empty">No apps marked Published yet. Confirm approval in the CA portal, then update each app in Submissions.</div>'}catch(error){box.innerHTML=`<div class="history-empty">${escapeHtml(error.message)}</div>`}}
function pluginRow(item){const status=getSubmissionStatuses()[item.file]||'Draft';return `<article class="application-row"><div class="application-icon">PL</div><div class="application-main"><b>${escapeHtml(item.name||item.file)}</b><small>${escapeHtml(item.file)}</small><div class="application-meta"><span class="pill ${item.ok?'good':'pending'}">${item.ok?'VALID':'FIX REQUIRED'}</span><span class="application-status">Submission: ${escapeHtml(status)}</span></div>${item.plugin_url?`<p>Package: <a href="${escapeHtml(item.plugin_url)}" target="_blank" rel="noreferrer">${escapeHtml(item.plugin_url)}</a></p>`:''}${item.errors?.length?`<ul class="application-errors">${item.errors.map(error=>`<li>${escapeHtml(error)}</li>`).join('')}</ul>`:'<div class="application-valid-note">Plugin wrapper validation passed.</div>'}</div></article>`}
