async function loadPluginStats(){const box=document.querySelector('#publishedPluginStats');try{const{plugins}=await getPluginTemplates(),published=plugins.filter(item=>getSubmissionStatuses()[item.file]==='Published');box.dataset.pluginFiles=JSON.stringify(published.map(item=>({file:item.file,name:item.name||item.file})));box.innerHTML=published.length?published.map((item,index)=>`<article class="application-row"><div class="application-icon">PL</div><div class="application-main"><b>${escapeHtml(item.name||item.file)}</b><small>${escapeHtml(item.file)}</small><div class="application-metrics-content" data-plugin-metrics="${index}">Load statistics from the CA Store.</div><button type="button" class="outline" data-plugin-stats="${index}">Load statistics</button></div></article>`).join(''):'<div class="history-empty">No plugins marked Published yet. Confirm approval in the CA portal, then update each plugin in Submissions.</div>'}catch(error){box.innerHTML=`<div class="history-empty">${escapeHtml(error.message)}</div>`}}

