let repoIconUploadPath='',iconPreviewUrl='';let templateEditorIsNew=false;function isRepositoryIcon(path){return /(^|\/)icon\.(png|jpe?g|webp|svg)$/i.test(path)}
async function viewRepoFile(name){if(name==='ca_profile.xml'){await navigate('profile-editor');return}if(isRepositoryIcon(name)){repoIconUploadPath=name;const input=document.querySelector('#iconUploadInput'),extension=name.split('.').pop().toLowerCase(),accept={png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',webp:'image/webp',svg:'image/svg+xml'}[extension];document.querySelector('#iconUploadPath').textContent=`${name} · upload a replacement`;document.querySelector('#iconUploadStatus').textContent='';document.querySelector('#iconUploadPreview').hidden=true;document.querySelector('#saveIconUpload').disabled=true;input.value='';input.accept=accept;document.querySelector('#iconUploadDialog').hidden=false;return}try{const d=await api(`/api/repo/file?path=${encodeURIComponent(name)}`);document.querySelector('#repoEditorPath').value=d.name;document.querySelector('#repoEditorContent').value=d.content;document.querySelector('#repoEditorTitle').textContent='Edit repository file';document.querySelector('#repoEditorStatus').textContent='Changes are saved locally and are not pushed to GitHub automatically.';document.querySelector('#deleteRepoFile').hidden=false;document.querySelector('#repoEditorDialog').hidden=false}catch(e){toast(e.message)}}
document.querySelector('#iconUploadInput').addEventListener('change',event=>{const file=event.target.files[0],extension=repoIconUploadPath.split('.').pop().toLowerCase(),expected={png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',webp:'image/webp',svg:'image/svg+xml'}[extension],status=document.querySelector('#iconUploadStatus'),preview=document.querySelector('#iconUploadPreview'),save=document.querySelector('#saveIconUpload');if(iconPreviewUrl)URL.revokeObjectURL(iconPreviewUrl);iconPreviewUrl='';if(!file){save.disabled=true;preview.hidden=true;return}if(file.size>2_000_000||file.type&&file.type!==expected){status.textContent='Choose an image under 2 MB in the same format as the current icon.';save.disabled=true;preview.hidden=true;return}status.textContent=file.name;iconPreviewUrl=URL.createObjectURL(file);preview.src=iconPreviewUrl;preview.hidden=false;save.disabled=false});
function closeIconUploader(){document.querySelector('#iconUploadDialog').hidden=true;document.querySelector('#iconUploadInput').value='';document.querySelector('#iconUploadPreview').hidden=true;if(iconPreviewUrl)URL.revokeObjectURL(iconPreviewUrl);iconPreviewUrl=''}document.querySelector('#closeIconUpload').addEventListener('click',closeIconUploader);document.querySelector('#cancelIconUpload').addEventListener('click',closeIconUploader);document.querySelector('#iconUploadDialog').addEventListener('click',event=>{if(event.target.id==='iconUploadDialog')closeIconUploader()});document.querySelector('#saveIconUpload').addEventListener('click',async()=>{const file=document.querySelector('#iconUploadInput').files[0],status=document.querySelector('#iconUploadStatus'),button=document.querySelector('#saveIconUpload'),extension=repoIconUploadPath.split('.').pop().toLowerCase(),mime=file?.type||({png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',webp:'image/webp',svg:'image/svg+xml'}[extension]);if(!file||!repoIconUploadPath)return;button.disabled=true;status.textContent='Uploading the new icon…';try{const encoded=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('The selected image could not be read.'));reader.readAsDataURL(file)});await api('/api/repo/file/upload',{method:'POST',body:JSON.stringify({path:repoIconUploadPath,type:mime,data:encoded})});markRepoFileSaved(repoIconUploadPath);closeIconUploader();toast('Repository icon saved locally.');await loadRepoFiles();try{const data=await api('/api/status');drawRepo(data.repo);await loadActivity()}catch(error){toast(`Icon saved, but the repository view could not refresh: ${error.message}`)}}catch(error){status.textContent=error.message;toast(error.message)}finally{button.disabled=false}});
