document.querySelector('#closeRepoEditor').addEventListener('click',()=>document.querySelector('#repoEditorDialog').hidden=true);document.querySelector('#repoEditorDialog').addEventListener('click',e=>{if(e.target.id==='repoEditorDialog')e.currentTarget.hidden=true});document.querySelector('#saveRepoFile').addEventListener('click',async()=>{const path=document.querySelector('#repoEditorPath').value.trim(),status=document.querySelector('#repoEditorStatus');if(!path){toast('Enter a file path first.');return}if(isApplicationAsset(path)){status.textContent='Docker templates and app icons are managed in Applications.';return}const button=document.querySelector('#saveRepoFile');button.disabled=true;try{await api('/api/repo/file/save',{method:'POST',body:JSON.stringify({path,content:document.querySelector('#repoEditorContent').value})});markRepoFileSaved(path);document.querySelector('#repoEditorDialog').hidden=true;toast('Repository file saved locally.');document.querySelector('#repoEditorDialog').hidden=true;;await loadRepoFiles();try{const current=await api('/api/status');drawRepo(current.repo);await loadActivity()}catch(error){toast(`Saved, but the repository view could not refresh: ${error.message}`)}}catch(e){status.textContent=e.message;toast(e.message)}finally{button.disabled=false}});document.querySelector('#deleteRepoFile').addEventListener('click',async()=>{const path=document.querySelector('#repoEditorPath').value;if(!path||!confirm(`Delete ${path} from this local repository?`))return;try{await api('/api/repo/file/delete',{method:'POST',body:JSON.stringify({path})});markRepoFileDeleted(path);document.querySelector('#repoEditorDialog').hidden=true;await loadRepoFiles();const current=await api('/api/status');drawRepo(current.repo);await loadActivity();toast('Repository file deleted locally.')}catch(e){toast(e.message)}});
async function loadActivity(){try{const {events=[]}=await api('/api/history'),box=document.querySelector('#activityHistory');box.className=events.length?'activity-list':'history-empty';box.innerHTML=events.length?events.slice().reverse().map(e=>`<div class="activity-row"><b>${escapeHtml(e.action)}</b><small>${escapeHtml(e.detail)} · ${escapeHtml(new Date(e.time).toLocaleString())}</small></div>`).join(''):'<div>◷</div><b>No local activity yet</b><p>Connect a repository or run a preflight to begin.</p>';const validation=events.find(e=>e.action==='Local preflight');document.querySelector('#validationDate').textContent=validation?new Date(validation.time).toLocaleDateString():'—';document.querySelector('#validationLabel').textContent=validation?new Date(validation.time).toLocaleTimeString():'Not run yet'}catch(e){toast(e.message)}}
async function loadUnraidStatus(){try{const d=await api('/api/unraid/status'),box=document.querySelector('#unraidStatus'),disconnect=document.querySelector('#unraidDisconnect'),list=document.querySelector('#unraidContainers');disconnect.hidden=!d.connected;if(!d.connected){box.innerHTML='Not connected. This app requests <code>system:read</code>, <code>docker:read</code>, <code>docker:update</code>, and <code>docker:delete</code>.';list.innerHTML='';return}document.querySelector('#unraidHost').value=d.host||'';if(d.error){box.textContent=`Connected to ${d.host}, but the API check failed: ${d.error}`;list.innerHTML='';return}const os=d.os||{};box.innerHTML=`<b>Connected to ${escapeHtml(d.host)}</b><span>${escapeHtml([os.distro,os.release].filter(Boolean).join(' ')||os.platform||'Unraid OS')} · ${Number(d.container_count)||0} Docker containers</span>`;renderUnraidContainers(d.containers||[])}catch(e){toast(e.message)}}
function renderSyncStatus(status){const box=document.querySelector('#syncStatus'),list=document.querySelector('#syncFileList'),button=document.querySelector('#syncRepository');if(!status.connected){box.innerHTML=`<span class="sync-state pending">Repository unavailable</span><p>${escapeHtml(status.error||'Connect a repository first.')}</p>`;list.innerHTML='';button.disabled=true;return}const publicOk=status.public_check?.ok===true;box.innerHTML=`<span class="sync-state ${status.synced?'good':'pending'}">${status.synced?'SYNCED TO GITHUB':publicOk?'SYNC REQUIRED':'CHECK REQUIRED'}</span><p>Local folder <code>${escapeHtml(status.repository_path||'unknown')}</code> · GitHub <b>${escapeHtml(status.remote_name||'repository')}</b> · branch <code>${escapeHtml(status.branch||'unknown')}</code>${status.ahead?` · ${status.ahead} local commit(s) to push`:''}${status.behind?` · ${status.behind} remote commit(s) to pull`:''}</p>${status.error?`<small>${escapeHtml(status.error)}</small>`:''}${publicOk?'<small class="sync-public good-text">Repository is public and active.</small>':`<small class="sync-public">${escapeHtml(status.public_check?.detail||'GitHub repository visibility is not verified.')}</small>`}`;const files=status.syncable_files||[],other=status.other_changes||[];list.innerHTML=files.length?`<b>Submission files ready to sync</b>${files.map(file=>`<div>${escapeHtml(file)}</div>`).join('')}`:other.length?'<b>No supported app files are waiting to sync.</b>':'<span>No local app file changes.</span>';if(other.length)list.innerHTML+=`<div class="sync-other"><b>Other changes will be left out of this sync</b>${other.map(file=>`<div>${escapeHtml(file)}</div>`).join('')}</div>`;button.disabled=!files.length&&!status.ahead||status.behind>0||!status.branch;document.querySelector('#syncCommitMessage').disabled=button.disabled}
const COMMON_INSTALL_VARS_KEY='ca-workshop-common-install-vars';function getCommonInstallVariables(){try{const data=JSON.parse(localStorage.getItem(COMMON_INSTALL_VARS_KEY)||'{}');return data&&typeof data==='object'&&!Array.isArray(data)?data:{}}catch{return {}}}
function addCommonInstallVarRow(name='',value=''){const row=document.createElement('div');row.className='common-install-var-row';const nameLabel=document.createElement('label'),nameInput=document.createElement('input');nameLabel.textContent='Variable name';nameInput.className='common-var-name';nameInput.value=name;nameInput.placeholder='PUID';nameInput.autocomplete='off';nameLabel.append(nameInput);const valueLabel=document.createElement('label');valueLabel.textContent='Saved value';const valueInput=document.createElement('input');valueInput.className='common-var-value';valueInput.type='password';valueInput.value=value;valueInput.autocomplete='off';valueInput.placeholder='1000';valueLabel.append(valueInput);const reveal=document.createElement('label');reveal.className='common-var-reveal';const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.addEventListener('change',()=>valueInput.type=checkbox.checked?'text':'password');reveal.append(checkbox,document.createTextNode('Show'));const remove=document.createElement('button');remove.type='button';remove.className='outline common-var-remove';remove.textContent='Remove';remove.addEventListener('click',()=>row.remove());row.append(nameLabel,valueLabel,reveal,remove);document.querySelector('#commonInstallVars').append(row)}
function renderCommonInstallVariables(){const box=document.querySelector('#commonInstallVars');box.replaceChildren();const values=getCommonInstallVariables();for(const[name,value]of Object.entries(values))addCommonInstallVarRow(name,String(value));document.querySelector('#commonInstallVarsStatus').textContent=Object.keys(values).length?`${Object.keys(values).length} variable(s) saved on this server.`:'No variables saved yet.'}
document.querySelector('#addCommonInstallVar').addEventListener('click',()=>{addCommonInstallVarRow();document.querySelector('#commonInstallVars .common-var-name:last-of-type')?.focus()});document.querySelector('#commonInstallVarsForm').addEventListener('submit',async event=>{event.preventDefault();const values={},rows=[...document.querySelectorAll('.common-install-var-row')];for(const row of rows){const name=row.querySelector('.common-var-name').value.trim(),value=row.querySelector('.common-var-value').value;if(!name&&!value)continue;if(!/^[A-Za-z_][A-Za-z0-9_]*$/.test(name)){row.querySelector('.common-var-name').focus();document.querySelector('#commonInstallVarsStatus').textContent='Use variable names with letters, numbers, and underscores.';return}values[name]=value}await api('/api/settings/vars',{method:'POST',body:JSON.stringify({vars:values})});document.querySelector('#commonInstallVarsStatus').textContent=`Saved ${Object.keys(values).length} common variable(s) in this browser.`;toast('Common install variables saved.')});
async function loadSettings(){try{const data=await api('/api/settings');const github=data.github||{},badge=document.querySelector('#githubSettingsBadge');renderCommonInstallVariables();badge.className=`pill ${github.configured?'good':'pending'}`;badge.textContent=github.configured?`CONNECTED · ${github.login||'GITHUB'}`:'NOT CONNECTED';document.querySelector('#githubSettingsStatus').textContent=github.configured?`Token verified for ${github.login}. Enter a new token to replace it.`:'No GitHub token saved.';document.querySelector('#removeGithubToken').hidden=!github.configured;const widget=data.dashboard_widget||{},widgetToggle=document.querySelector('#dashboardWidgetToggle'),widgetBadge=document.querySelector('#dashboardWidgetBadge');if(widgetToggle){widgetToggle.checked=widget.enabled!==false;if(widgetBadge){widgetBadge.className=`pill ${widgetToggle.checked?'good':'pending'}`;widgetBadge.textContent=widgetToggle.checked?'ENABLED':'DISABLED'}}renderSyncStatus(data.sync||{});loadAISettings();loadRuntime();await loadUnraidStatus()}catch(error){document.querySelector('#syncStatus').textContent=error.message}}
document.querySelector('#refreshSettings').addEventListener('click',loadSettings);document.querySelector('#refreshSyncStatus').addEventListener('click',async()=>{try{renderSyncStatus(await api('/api/repo/sync/status'))}catch(error){toast(error.message)}});document.querySelector('#settingsThemeToggle').addEventListener('click',()=>document.querySelector('#themeToggle').click());
