document.querySelector('#githubSettingsForm').addEventListener('submit',async event=>{event.preventDefault();const token=document.querySelector('#settingsGithubToken').value.trim(),status=document.querySelector('#githubSettingsStatus'),button=event.currentTarget.querySelector('button[type=submit]');if(!token){status.textContent='Paste a GitHub token first.';return}button.disabled=true;status.textContent='Verifying the token with GitHub…';try{const result=await api('/api/settings/github',{method:'POST',body:JSON.stringify({token})});document.querySelector('#settingsGithubToken').value='';status.textContent=`Verified and saved for ${result.login}.`;toast('GitHub token saved securely on this computer.');await loadSettings()}catch(error){status.textContent=error.message;toast(error.message)}finally{button.disabled=false}});document.querySelector('#removeGithubToken').addEventListener('click',async()=>{if(!confirm('Remove the saved GitHub token from this computer?'))return;try{await api('/api/settings/github/remove',{method:'POST',body:'{}'});document.querySelector('#settingsGithubToken').value='';toast('Saved GitHub token removed.');await loadSettings()}catch(error){toast(error.message)}});
document.querySelector('#syncForm').addEventListener('submit',async event=>{event.preventDefault();const button=document.querySelector('#syncRepository');button.disabled=true;try{const status=await api('/api/repo/sync/status'),files=status.syncable_files||[];if(status.behind){toast(status.error||'Pull remote changes before syncing.');return}const message=document.querySelector('#syncCommitMessage').value.trim();if(!message){toast('Enter a commit message.');return}const summary=files.length?files.join('\n'):status.ahead?`${status.ahead} existing local commit(s)`:'';if(!summary){toast('There are no app files or local commits to push.');return}if(!confirm(`Commit and push these changes to ${status.remote_name} on ${status.branch}?\n\n${summary}`))return;button.textContent='Pushing to GitHub…';const result=await api('/api/repo/sync',{method:'POST',body:JSON.stringify({message})});renderSyncStatus(result.status);toast(`Repository synced to GitHub (${result.branch}).`);await loadActivity()}catch(error){toast(error.message);await loadSettings()}finally{button.textContent='Commit submission files & push';button.disabled=false}});
function renderUnraidContainers(containers){const box=document.querySelector('#unraidContainers');if(!containers.length){box.innerHTML='<div class="unraid-empty">No Docker containers found on this Unraid server.</div>';return}box.innerHTML='<h3>Unraid Docker containers</h3>'+containers.map(c=>{const id=escapeHtml(c.id),state=String(c.state).toLowerCase(),stateButtons=state==='running'?`<button data-unraid-action="stop" data-id="${id}">Stop</button><button data-unraid-action="restart" data-id="${id}">Restart</button>`:`<button data-unraid-action="start" data-id="${id}">Start</button>`;return `<div class="unraid-container-row"><div><b>${escapeHtml(c.name||'Unnamed container')}</b><small>${escapeHtml(c.image||'')} · ${escapeHtml(c.status||c.state||'Unknown status')}</small></div><div class="unraid-container-actions">${stateButtons}<button data-unraid-action="update" data-id="${id}">Update</button><button class="danger-button" data-unraid-action="remove" data-id="${id}">Remove</button></div></div>`}).join('')}
document.querySelector('#unraidContainers').addEventListener('click',async e=>{const button=e.target.closest('[data-unraid-action]');if(!button)return;const {unraidAction:action,id}=button.dataset,verb={start:'Start',stop:'Stop',restart:'Restart',update:'Update from the latest image',remove:'Remove'}[action];if(!confirm(`${verb} ${action==='remove'?'this container?':'this Unraid container?'}${action==='update'?' This pulls and applies its latest image.':''}${action==='remove'?' The container will be removed; its image will be kept.':''}`))return;button.disabled=true;try{await api('/api/unraid/docker/action',{method:'POST',body:JSON.stringify({action,id,confirmed:true})});toast(`Unraid container ${action} request completed.`);await loadUnraidStatus();loadActivity()}catch(error){toast(error.message)}finally{button.disabled=false}});
async function completeUnraidCallback(){const params=new URLSearchParams(location.search),apiKey=params.get('api_key'),state=params.get('state'),error=params.get('error');if(!apiKey&&!error)return;history.replaceState({},document.title,location.pathname);if(error){toast('Unraid authorization was not completed.');return}try{await api('/api/unraid/connect/complete',{method:'POST',body:JSON.stringify({api_key:apiKey,state})});toast('Unraid server connected.');await loadUnraidStatus();loadActivity()}catch(e){toast(e.message)}}
document.querySelector('#unraidConnectForm').addEventListener('submit',async ev=>{ev.preventDefault();const tab=window.open('about:blank','_blank');const button=ev.currentTarget.querySelector('button');button.disabled=true;try{const d=await api('/api/unraid/connect/start',{method:'POST',body:JSON.stringify({host:document.querySelector('#unraidHost').value})});if(tab)tab.location=d.authorization_url;else window.location.href=d.authorization_url}catch(e){if(tab)tab.close();toast(e.message)}finally{button.disabled=false}});document.querySelector('#unraidDisconnect').addEventListener('click',async()=>{try{await api('/api/unraid/disconnect',{method:'POST',body:'{}'});toast('Unraid server disconnected.');await loadUnraidStatus();loadActivity()}catch(e){toast(e.message)}});
async function canOpenSubmissionPortal(){try{const status=await api('/api/repo/sync/status');if(status.synced)return true;toast(status.error||'Sync the public repository to GitHub before opening CA submission.');await navigate('settings');return false}catch(error){toast(`Could not verify GitHub sync: ${error.message}`);await navigate('settings');return false}}
document.querySelector('#reloadCAPortal').addEventListener('click',async()=>{if(await canOpenSubmissionPortal())document.querySelector('#caSubmissionFrame').src='https://ca.unraid.net/submit/new'});document.querySelectorAll('a[href="https://ca.unraid.net/submit/new"]').forEach(link=>link.addEventListener('click',async event=>{event.preventDefault();const tab=window.open('about:blank','_blank');if(tab)tab.opener=null;if(await canOpenSubmissionPortal()){if(tab)tab.location.href=link.href;else toast('Allow popups to open the CA submission portal.')}else if(tab)tab.close()}));
function templateEditorLabel(value){return String(value).replace(/([a-z0-9])([A-Z])/g,'$1 $2').replace(/[_-]+/g,' ').replace(/^./,letter=>letter.toUpperCase())}
function templateEditorInput(label,value,attrs){const data=Object.entries(attrs).map(([key,val])=>`data-${key}="${escapeHtml(val)}"`).join(' '),boolean=/^(Required|Mask)$/i.test(label);if(boolean)return `<label>${escapeHtml(templateEditorLabel(label))}<select ${data}><option value="false" ${String(value).toLowerCase()==='false'?'selected':''}>No</option><option value="true" ${String(value).toLowerCase()==='true'?'selected':''}>Yes</option></select></label>`;const long=/Overview|Description|Changes|Support|WebUI/i.test(label),secret=/^Default$/i.test(label)&&attrs.masked==='true';return `<label>${escapeHtml(templateEditorLabel(label))}${long?`<textarea ${data} rows="3">${escapeHtml(value)}</textarea>`:`<input type="${secret?'password':'text'}" ${data} value="${escapeHtml(value)}" autocomplete="off">`}</label>`}
function templateEditorXml(){if(!templateEditorDocument)return '';const root=templateEditorDocument.documentElement,children=[...root.children],direct=children.filter(node=>node.tagName!=='Config'&&!node.children.length);document.querySelectorAll('[data-template-root-index]').forEach(field=>{const node=direct[Number(field.dataset.templateRootIndex)];if(node)node.textContent=field.value});document.querySelectorAll('[data-template-new-element]').forEach(field=>{const tag=field.dataset.templateNewElement;let node=[...root.children].find(child=>child.tagName===tag);if(!node&&field.value.trim()){node=templateEditorDocument.createElement(tag);root.append(node)}if(node)node.textContent=field.value});document.querySelectorAll('[data-template-root-attribute]').forEach(field=>root.setAttribute(field.dataset.templateRootAttribute,field.value));const configs=[...root.children].filter(node=>node.tagName==='Config');document.querySelectorAll('[data-config-index][data-config-attribute]').forEach(field=>{const node=configs[Number(field.dataset.configIndex)];if(node)node.setAttribute(field.dataset.configAttribute,field.value)});const serialized=new XMLSerializer().serializeToString(templateEditorDocument).replace(/^(?:\s*<\?xml[^?]*\?>)+\s*/i,'');return `<?xml version="1.0" encoding="UTF-8"?>\n${serialized}`}
function refreshTemplateEditorPreview(){document.querySelector('#templateEditorPreview').textContent=templateEditorXml()}
function renderTemplateEditor(){
 const root=templateEditorDocument.documentElement,form=document.querySelector('#templateEditorForm'),configsBox=document.querySelector('#templateEditorConfigs'),direct=[...root.children].filter(node=>node.tagName!=='Config'&&!node.children.length);
 const fields=direct.map((node,index)=>templateEditorInput(node.tagName,node.textContent,{'template-root-index':index}));
 if(root.tagName==='Container'){
  const present=new Set(direct.map(node=>node.tagName));
  ['Name','Repository','Network','Overview','Support','Project','WebUI'].filter(tag=>!present.has(tag)).forEach(tag=>fields.push(templateEditorInput(tag,'',{'template-new-element':tag})));
 }
 const rootAttributes=[...root.attributes];
 if(rootAttributes.length)fields.unshift(...rootAttributes.map(attr=>templateEditorInput(attr.name,attr.value,{'template-root-attribute':attr.name})));
 form.innerHTML=fields.join('');
 const configs=[...root.children].filter(node=>node.tagName==='Config');
 const cards=configs.map((config,index)=>{
  const settingName=config.getAttribute('Name')||('Setting '+(index+1));
  const attrs=[...config.attributes].map(attr=>templateEditorInput(attr.name,attr.value,{'config-index':index,'config-attribute':attr.name,masked:config.getAttribute('Mask')?.toLowerCase()||'false'})).join('');
  return '<section class="template-config-card"><div class="template-config-heading"><b>'+escapeHtml(settingName)+'</b><span>'+escapeHtml(config.getAttribute('Type')||'Config')+'</span></div><div class="template-config-fields">'+attrs+'</div></section>';
 }).join('');
 configsBox.innerHTML=configs.length?'<h2>Container settings</h2>'+cards:'<div class="history-empty">This template has no Config settings yet.</div>';
 document.querySelector('#templateEditorWorkspace').hidden=false;document.querySelector('#templateEditorEmpty').hidden=true;refreshTemplateEditorPreview();
}
async function loadTemplateEditor(){const select=document.querySelector('#templateEditorSelect'),status=document.querySelector('#templateEditorStatus'),previous=select.value;try{const data=await api('/api/status'),templates=(data.repo?.templates||[]).filter(item=>item.kind==='docker');select.innerHTML='<option value="">Choose a template file…</option>'+templates.map(item=>`<option value="${escapeHtml(item.file)}">${escapeHtml(item.name||item.file)} · ${escapeHtml(item.file)}</option>`).join('');status.textContent=data.repo?.connected?`${templates.length} Docker application template(s) available.`:'Connect a repository to load templates.';select.disabled=!data.repo?.connected;document.querySelector('#saveVisualTemplate').disabled=!data.repo?.connected;document.querySelector('#startDummyTemplate').disabled=!data.repo?.connected;if(previous&&templates.some(item=>item.file===previous)){select.value=previous;await loadTemplateEditorFile(previous)}else{select.value='';templateEditorDocument=null;templateEditorPath='';templateEditorIsNew=false;document.querySelector('#templateEditorFilePath').value='';document.querySelector('#templateEditorWorkspace').hidden=true;document.querySelector('#templateEditorEmpty').hidden=false;document.querySelector('#templateEditorEmpty').textContent=data.repo?.connected?'Choose a template XML file or start from the dummy example.':'Connect a repository to begin.'}}catch(error){status.textContent=error.message}}
async function loadTemplateEditorFile(path){const status=document.querySelector('#templateEditorStatus');if(!path){templateEditorDocument=null;document.querySelector('#templateEditorWorkspace').hidden=true;document.querySelector('#templateEditorEmpty').hidden=false;return}try{const data=await api(`/api/repo/file?path=${encodeURIComponent(path)}`),parsed=new DOMParser().parseFromString(data.content,'application/xml');if(parsed.querySelector('parsererror')||parsed.documentElement?.tagName!=='Container')throw Error('This file is not a valid Docker Container template XML.');templateEditorDocument=parsed;templateEditorPath=path;templateEditorIsNew=false;document.querySelector('#templateEditorFilePath').value=path;status.textContent=`Editing ${path}. Changes are saved to your local repository.`;renderTemplateEditor()}catch(error){templateEditorDocument=null;document.querySelector('#templateEditorWorkspace').hidden=true;document.querySelector('#templateEditorEmpty').hidden=false;document.querySelector('#templateEditorEmpty').textContent=error.message}}
document.querySelector('#startDummyTemplate').addEventListener('click',async()=>{if(!repo?.connected){toast('Connect a repository before starting a template.');return}if(!document.querySelector('#templateEditorWorkspace').hidden&&!confirm('Start a new template and discard the current unsaved editor changes?'))return;const button=document.querySelector('#startDummyTemplate'),status=document.querySelector('#templateEditorStatus');button.disabled=true;try{const [response,listing]=await Promise.all([fetch(apiUrl('/api/template/dummy'),{headers:{'X-CA-Workshop':'1'}}),api('/api/repo/files')]);if(!response.ok)throw Error('The example template could not be loaded.');const payload=await response.json(),source=payload.content||'',parsed=new DOMParser().parseFromString(source,'application/xml');if(parsed.querySelector('parsererror'))throw Error('The bundled example template is not valid XML.');const files=new Set(listing.files||[]);let index=1,path='templates/new-app.xml';while(files.has(path)){index+=1;path=`templates/new-app-${index}.xml`}templateEditorDocument=parsed;templateEditorPath=path;templateEditorIsNew=true;document.querySelector('#templateEditorFilePath').value=path;document.querySelector('#templateEditorSelect').value='';status.textContent='Started from the dummy XML example. Replace its sample values, then save into templates/.';renderTemplateEditor()}catch(error){status.textContent=error.message;toast(error.message)}finally{button.disabled=false}});document.querySelector('#templateEditorSelect').addEventListener('change',event=>loadTemplateEditorFile(event.target.value));function handleTemplateEditorChange(event){const field=event.target;if(field.dataset.configAttribute==='Mask'){const value=document.querySelector(`[data-config-index="${field.dataset.configIndex}"][data-config-attribute="Default"]`);if(value)value.type=field.value==='true'?'password':'text'}refreshTemplateEditorPreview()}document.querySelector('#templateEditorWorkspace').addEventListener('input',handleTemplateEditorChange);document.querySelector('#templateEditorWorkspace').addEventListener('change',handleTemplateEditorChange);document.querySelector('#saveVisualTemplate').addEventListener('click',async()=>{if(!templateEditorDocument)return;const button=document.querySelector('#saveVisualTemplate'),status=document.querySelector('#templateEditorStatus'),savedPath=document.querySelector('#templateEditorFilePath').value.trim(),parts=savedPath.split('/');if(!savedPath.endsWith('.xml')||parts[0]!=='templates'||parts.some(part=>!part||part==='.'||part==='..')||savedPath.includes('\\')){status.textContent='Choose an XML file path inside templates/.';return}button.disabled=true;try{if(templateEditorIsNew){const listing=await api('/api/repo/files');if((listing.files||[]).includes(savedPath)&&!confirm(`${savedPath} already exists. Replace it?`))return}await api('/api/repo/file/save',{method:'POST',body:JSON.stringify({path:savedPath,content:templateEditorXml()})});templateEditorPath=savedPath;templateEditorIsNew=false;markRepoFileSaved(savedPath);status.textContent=`Saved ${savedPath} locally. Commit and push it from Git when ready.`;await loadRepoFiles();const data=await api('/api/status');drawRepo(data.repo);await loadActivity();toast('Template saved locally.');navigate('applications')}catch(error){status.textContent=error.message;toast(error.message)}finally{button.disabled=false}});
async function loadComposePage(){try{const data=await api('/api/status'),label=document.querySelector('#composeRepoStatus');label.textContent=data.repo?.connected?`Saving into ${data.repo.name}/templates/`:'Connect a repository first; you can still generate and review templates.';document.querySelector('#saveComposeTemplates').disabled=!data.repo?.connected}catch(error){document.querySelector('#composeRepoStatus').textContent=error.message}}
document.querySelector('#composeFileInput').addEventListener('change',async event=>{const file=event.target.files?.[0];if(!file)return;if(file.size>1_000_000){toast('Compose files must be smaller than 1 MB.');event.target.value='';return}try{document.querySelector('#composeSource').value=await file.text();document.querySelector('#composeSource').dataset.filename=file.name;document.querySelector('#composeMessage').textContent=`Loaded ${file.name}. Review it, then generate templates.`}catch(error){toast(`Could not read the file: ${error.message}`)}});
document.querySelector('#composeForm').addEventListener('submit',async event=>{event.preventDefault();const content=document.querySelector('#composeSource').value,button=document.querySelector('#convertCompose'),message=document.querySelector('#composeMessage');button.disabled=true;button.textContent='Generating…';message.textContent='Reading services and mapping Compose settings…';try{const result=await api('/api/compose/convert',{method:'POST',body:JSON.stringify({content})});composeTemplates=result.templates||[];document.querySelector('#composeResults').innerHTML=composeTemplates.map((template,index)=>`<details class="compose-template" ${index===0?'open':''}><summary><span>${escapeHtml(template.service)}</span><small>${escapeHtml(template.image)} · ${escapeHtml(template.path)}</small></summary>${template.warnings.length?`<div class="compose-warnings"><b>Review these items</b><ul>${template.warnings.map(warning=>`<li>${escapeHtml(warning)}</li>`).join('')}</ul></div>`:`<div class="compose-success">Compose values mapped into the dummy template. Review the remaining example URLs and settings in the graphical editor.</div>`}<label>Template file path<input data-compose-path value="${escapeHtml(template.path)}" autocomplete="off"></label><button type="button" class="outline" data-compose-edit="${index}">Continue in graphical editor</button></details>`).join('');document.querySelector('#saveComposeTemplates').hidden=true;message.textContent=`Generated ${composeTemplates.length} template${composeTemplates.length===1?'':'s'}. Check each warning and review the XML before saving.`;await loadComposePage()}catch(error){message.textContent=error.message;document.querySelector('#composeResults').innerHTML='';document.querySelector('#saveComposeTemplates').hidden=true;composeTemplates=[]}finally{button.disabled=false;button.textContent='Generate templates'}});
async function openComposeTemplateInEditor(index){const template=composeTemplates[index];if(!template)return;template.path=document.querySelector(`[data-compose-edit="${index}"]`).closest('.compose-template').querySelector('[data-compose-path]').value.trim();await navigate('template-editor');const parsed=new DOMParser().parseFromString(template.content,'application/xml');if(parsed.querySelector('parsererror')){toast('The generated template could not be opened in the graphical editor.');return}templateEditorDocument=parsed;templateEditorPath=template.path;templateEditorIsNew=true;document.querySelector('#templateEditorSelect').value='';document.querySelector('#templateEditorFilePath').value=template.path;document.querySelector('#templateEditorStatus').textContent=`Compose settings were mapped into the dummy template. Review the values, icon URL, and template URL before saving.`;renderTemplateEditor()}
document.querySelector('#composeResults').addEventListener('click',event=>{const button=event.target.closest('[data-compose-edit]');if(button)openComposeTemplateInEditor(Number(button.dataset.composeEdit)).catch(error=>toast(error.message))});
document.querySelector('#saveComposeTemplates').addEventListener('click',async()=>{if(!composeTemplates.length)return;const templates=[...document.querySelectorAll('.compose-template')].map(card=>({path:card.querySelector('[data-compose-path]').value.trim(),content:card.querySelector('[data-compose-content]').value}));const fileList=templates.map(item=>item.path).join('\n');if(!confirm(`Save these ${templates.length} template file(s) into your connected repository?\n\n${fileList}\n\nExisting files with the same names will be replaced.`))return;const button=document.querySelector('#saveComposeTemplates');button.disabled=true;try{const result=await api('/api/compose/save',{method:'POST',body:JSON.stringify({templates,overwrite:true})});document.querySelector('#composeMessage').textContent=`Saved ${result.files.length} template file(s) locally. Review, commit, and push them from your repository.`;toast('Compose templates saved to the repository.');const current=await api('/api/status');drawRepo(current.repo);await loadActivity()}catch(error){document.querySelector('#composeMessage').textContent=error.message;toast(error.message)}finally{button.disabled=false}});
function renderPackageState(data){const badge=document.querySelector('#packageBadge'),message=document.querySelector('#packageMessage'),check=document.querySelector('#packageCheckUpdates'),download=document.querySelector('#packageDownloadUpdate'),pending=['checking','downloading'].includes(data.state);document.querySelector('#packageVersion').textContent=data.available?`Version ${data.current_version} · x86_64 · TXZ package`:pending?'Checking the official archive…':'No package downloaded yet';document.querySelector('#packageFilename').textContent=data.filename||'Official Unraid archive';badge.className=`pill ${data.update_available?'pending':data.available?'good':'pending'}`;badge.textContent=data.state==='downloading'?'DOWNLOADING':data.state==='checking'?'CHECKING':data.update_available?'UPDATE AVAILABLE':data.available?'ARCHIVE READY':'WAITING';message.textContent=data.state==='downloading'?`Downloading ${data.latest_version} · ${formatSize(data.bytes||0)} of ${formatSize(data.total||0)}`:data.state==='checking'?'Checking the official Unraid archive for the newest build…':data.state==='update-available'?`Version ${data.latest_version} is available.`:data.state==='up-to-date'?`Version ${data.current_version} is up to date.`:data.state==='downloaded'?`Downloaded and verified version ${data.current_version}.`:data.state==='failed'?`Archive check failed: ${data.error||'Unknown error'}`:data.available?'Use “Check for updates” to compare with GitHub.':'The latest package will download automatically.';check.disabled=pending;download.hidden=!data.update_available||pending;download.disabled=pending}
async function loadPackage(){clearTimeout(packagePollTimer);try{const data=await api('/api/package');renderPackageState(data);if(data.entries){const files=data.entries.filter(x=>x.type==='file');document.querySelector('#packageTree').innerHTML=`<div>▾ <b>${escapeHtml(data.archive)}</b> <i>${files.length} files</i></div>${files.slice(0,100).map(x=>`<button class="tree-item archive-file" data-file="${escapeHtml(x.name)}"><span>${escapeHtml(x.name.replace(/^\.\//,''))}</span><i>${formatSize(x.size)}</i></button>`).join('')}${files.length>100?`<div class="tree-item"><span>… ${files.length-100} more files</span></div>`:''}`;document.querySelectorAll('.archive-file').forEach(b=>b.addEventListener('click',()=>viewPackageFile(b.dataset.file)))}else if(data.state==='failed'){document.querySelector('#packageTree').textContent=data.error||'The official package could not be downloaded.'}else{document.querySelector('#packageTree').textContent=data.state==='downloading'?'Downloading the official Community Applications archive…':'Checking the official Community Applications archive…'}if(['checking','downloading'].includes(data.state))packagePollTimer=setTimeout(loadPackage,900)}catch(e){document.querySelector('#packageTree').textContent=e.message}}
async function requestPackageUpdate(path){const button=document.querySelector(path.endsWith('/download')?'#packageDownloadUpdate':'#packageCheckUpdates');button.disabled=true;try{const data=await api(path,{method:'POST',body:'{}'});renderPackageState(data);await loadPackage()}catch(e){toast(e.message)}finally{button.disabled=false}}
document.querySelector('#packageCheckUpdates')?.addEventListener('click',()=>requestPackageUpdate('/api/package/check'));document.querySelector('#packageDownloadUpdate')?.addEventListener('click',()=>requestPackageUpdate('/api/package/download'));
async function viewPackageFile(name){try{const d=await api(`/api/package?file=${encodeURIComponent(name)}`);document.querySelector('#fileTitle').textContent=name;document.querySelector('#fileContent').textContent=d.content;document.querySelector('#fileDialog').hidden=false}catch(e){toast(e.message)}}
document.querySelector('#closeFile').addEventListener('click',()=>document.querySelector('#fileDialog').hidden=true);document.querySelector('#fileDialog').addEventListener('click',e=>{if(e.target.id==='fileDialog')e.currentTarget.hidden=true});document.querySelector('#browseDialog').addEventListener('click',e=>{if(e.target.id==='browseDialog')e.currentTarget.hidden=true});
function formatSize(n){return n<1024?`${n} B`:n<1048576?`${(n/1024).toFixed(1)} KB`:`${(n/1048576).toFixed(1)} MB`}
async function loadDocker(){try{const d=await api('/api/status');drawRepo(d.repo);const available=d.docker.available;document.querySelector('#dockerBadge').innerHTML=`<i></i> ${available?'DOCKER CONNECTED':'DOCKER UNAVAILABLE'}`;document.querySelector('#dockerTitle').textContent=available?`Docker ${d.docker.version} connected`:'Docker connection required';document.querySelector('#dockerMessage').textContent=available?'Only running containers installed from the CA Store are listed.':'Start the Docker daemon to view CA Store sandbox containers.';document.querySelector('#dockerStatus').innerHTML=`<span class="${available?'green-dot':'red-dot'}"></span><span>${available?'Docker daemon is reachable':'Cannot connect to Docker API'}</span><button type="button" id="retryDocker">Retry</button>`;document.querySelector('#retryDocker').addEventListener('click',loadDocker);if(available)await loadContainers();else document.querySelector('#containers').innerHTML='<div class="history-empty">Docker is unavailable.</div>'}catch(e){toast(e.message)}}
async function loadContainers(){try{const d=await api('/api/docker/containers'),el=document.querySelector('#containers');el.innerHTML=d.containers.length?`<h3>Running CA Store apps</h3>${d.containers.map(c=>`<div class="container-row"><span><b>${escapeHtml(c.name)}</b><small>${escapeHtml(c.image)} · ${escapeHtml(c.status)} · ${escapeHtml(c.source||'CA Store')}</small></span><button data-stop="${escapeHtml(c.id)}">Stop &amp; remove</button></div>`).join('')}`:'<div class="history-empty"><div>◈</div><b>No running CA Store apps</b><p>Install a Docker app from the CA Store to start a sandbox session.</p></div>';el.querySelectorAll('[data-stop]').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Stop and remove this CA Store sandbox container?'))return;try{await api('/api/docker/stop',{method:'POST',body:JSON.stringify({id:b.dataset.stop})});toast('Container removed.');await loadContainers();loadActivity()}catch(e){toast(e.message)}}))}catch(e){toast(e.message)}}
document.querySelector('#refreshSandbox').addEventListener('click',loadDocker);
function showInstallConsole(name){const pane=document.querySelector('#installConsole');document.querySelector('#installConsoleTitle').textContent=`Installing ${name}`;document.querySelector('#installConsoleStage').textContent='Preparing install…';document.querySelector('#installConsoleLog').textContent='Waiting for Docker output…';pane.hidden=false;pane.classList.remove('install-done','install-failed');pane.scrollIntoView({block:'nearest'});return pane}
function appendConsoleLog(logs){const box=document.querySelector('#installConsoleLog');box.textContent=(logs||[]).join('\n')||'Docker is preparing the image and container…';box.scrollTop=box.scrollHeight}
async function watchInstall(jobId){let terminal=false;while(!terminal){try{const job=await api(`/api/docker/install/${encodeURIComponent(jobId)}`);document.querySelector('#installConsoleStage').textContent=job.stage||'Installing…';appendConsoleLog(job.logs);terminal=job.status==='complete'||job.status==='failed';if(terminal){const pane=document.querySelector('#installConsole');pane.classList.toggle('install-done',job.status==='complete');pane.classList.toggle('install-failed',job.status==='failed');if(job.error){const box=document.querySelector('#installConsoleLog');box.textContent+=(box.textContent?`\n\n${job.error}`:job.error)}if(job.status==='complete'){toast(`${job.result?.name||'App'} installed and started.`);await loadContainers();loadActivity()}else toast(job.error||'Docker install failed.')}else await new Promise(resolve=>setTimeout(resolve,700))}catch(e){document.querySelector('#installConsoleStage').textContent='Could not read install status';document.querySelector('#installConsoleLog').textContent=e.message;document.querySelector('#installConsole').classList.add('install-failed');terminal=true}}}
document.querySelector('#installConsoleClose').addEventListener('click',()=>{document.querySelector('#installConsole').hidden=true});
document.querySelector('#templateForm').addEventListener('submit',async ev=>{ev.preventDefault();const value=document.querySelector('#templateSelect').value,selected=value.startsWith('external:')?selectedExternalTemplate:installerTemplates.find(t=>t.file===value);if(!selected)return;const config={};document.querySelectorAll('[data-config]').forEach(input=>{const field=selected.configs[Number(input.dataset.config)];config[field.name]=input.value});document.querySelectorAll('[data-volume-mode]').forEach(mode=>{const index=Number(mode.dataset.volumeMode),field=selected.configs[index],source=document.querySelector(`[data-bind-source="${index}"]`).value.trim();config[field.name]=mode.value==='bind'?{mode:'bind',source}:{mode:'volume'}});const payload={...(selected.template_url?{template_url:selected.template_url}:{template:selected.file}),name:document.querySelector('#templateName').value,config};const pathCount=selected.configs.filter(c=>c.type.toLowerCase()==='path').length,bindCount=Object.values(config).filter(v=>v&&v.mode==='bind').length;const storageNote=bindCount?`${bindCount} bind mount(s) will expose selected host folders to the container.`:`${pathCount} path setting(s) will use isolated Docker volumes.`;if(!confirm(`Pull and install ${selected.name} (${selected.repository}) in Docker? This runs third-party image code. ${storageNote} Published ports are local to this computer.`))return;const button=ev.currentTarget.querySelector('button[type=submit]');button.disabled=true;button.textContent='Installing…';showInstallConsole(selected.name);try{const {job_id}=await api('/api/docker/run',{method:'POST',body:JSON.stringify(payload)});if(!job_id)throw Error('Docker install did not start.');await watchInstall(job_id)}catch(e){document.querySelector('#installConsoleStage').textContent='Docker install could not start';document.querySelector('#installConsoleLog').textContent=e.message;document.querySelector('#installConsole').classList.add('install-failed');toast(e.message)}finally{button.textContent='Install template to Docker';button.disabled=!selected.configs.every(c=>['port','path','variable'].includes(c.type.toLowerCase()))}});
document.querySelector('#inspect')?.addEventListener('click',loadPackage);

document.querySelector('#checkPackage').addEventListener('click',async()=>{try{const d=await api('/api/package');const badge=document.querySelector('#packageStatusBadge');badge.textContent=d.state==='idle'?'CHECKING':d.state;badge.className='pill '+(d.update_available?'warning':'ok');document.querySelector('#packageInfo').innerHTML=`<b>Version</b> ${escapeHtml(d.current_version||'-')} <b>Archive</b> ${escapeHtml(d.filename||'-')} <b>Latest</b> ${escapeHtml(d.latest_version||'-')} <b>Update available</b> ${(d.update_available?'Yes':'No')}`;renderPackageEntries(d.entries||[])}catch(e){toast(e.message)}});
document.querySelector('#showPackageContents').addEventListener('click',async()=>{document.querySelector('#packageOverlay').classList.remove('hidden');try{const d=await api('/api/package');renderPackageEntries(d.entries||[], true)}catch(e){toast(e.message)}});
document.querySelector('#closeOverlay').addEventListener('click',()=>{document.querySelector('#packageOverlay').classList.add('hidden')});
function renderPackageEntries(entries,overlay=false){const list=entries.filter(x=>x.type==='file').map(x=>`<div class="entry-row"><span class="entry-name">${escapeHtml(x.name.replace(/^\.\//,''))}</span><span class="entry-size">${formatSize(x.size)}</span></div>`).join('')||'<div class="history-empty">No entries.</div>';if(overlay){document.querySelector('#packageContents').innerHTML=`<div class="package-entries">${list}</div>`}else{document.querySelector('#packageInfo').innerHTML+=' <div class="package-entries"><b>Files (first 50)</b><div>'+list.slice(0,50).join('')+'</div></div>'}}
async function init(){loadActivity();await completeUnraidCallback();loadUnraidStatus();try{const d=await api('/api/status');drawRepo(d.repo)}catch(e){toast('Start the local server with python3 server.py')}}init();

document.querySelector('#editRawTemplate').addEventListener('click',async()=>{if(!templateEditorPath||!repo?.connected){toast('No template file loaded or repository not connected.');return}try{const d=await api('/api/repo/file?path='+encodeURIComponent(templateEditorPath));document.querySelector('#repoEditorPath').value=templateEditorPath;document.querySelector('#repoEditorContent').value=d.content;document.querySelector('#repoEditorStatus').textContent='Editing '+templateEditorPath;document.querySelector('#repoEditorDialog').hidden=false}catch(e){toast('Could not load raw file: '+e.message)}});
/* Local OpenAI-compatible AI assistant */
let aiEnhanceTimer=0;
const aiObserver=new MutationObserver(records=>{
  if(!aiConfig.configured)return;
  const added=records.some(record=>[...record.addedNodes].some(node=>node.nodeType===1&&(node.matches?.('input,textarea')||node.querySelector?.('input,textarea'))));
  if(!added)return;
  clearTimeout(aiEnhanceTimer);
  aiEnhanceTimer=setTimeout(()=>enhanceAIFields(document),40);
});
if(document.querySelector('main'))aiObserver.observe(document.querySelector('main'),{childList:true,subtree:true});

function aiFieldLabel(field){
  const configAttr=field.dataset.configAttribute;
  if(configAttr)return templateEditorLabel(configAttr);
  const label=field.closest('label');
  if(label){
    const clone=label.cloneNode(true);
    clone.querySelectorAll('input,textarea,select,button,small,.ai-field-control,.ai-suggestion').forEach(node=>node.remove());
    const text=clone.textContent.replace(/\s+/g,' ').trim();
    if(text)return text.replace(/\s*\(optional\)$/i,'');
  }
  return field.getAttribute('aria-label')||field.getAttribute('placeholder')||field.name||field.id||'Field';
}

function aiFieldAllowed(field){
  if(!field.matches('input,textarea'))return false;
  if(field.tagName==='INPUT'&&(field.type||'text')!=='text')return false;
  if(field.disabled||field.readOnly||field.dataset.aiEnhanced==='true')return false;
  if(field.closest('#aiSettingsForm, #syncForm, #unraidConnectForm, .repo-editor-box, .file-dialog, .template-xml-preview, #composeForm, #composeResults, .common-install-vars, .ca-install-drawer, .icon-tools-grid, .ai-suggestion'))return false;
  const label=aiFieldLabel(field);
  const key=[field.id,field.name,field.getAttribute('placeholder')||'',label,field.dataset.configAttribute||'',field.dataset.templateNewElement||''].join(' ');
  if(/(token|password|passwd|secret|api.?key|commit|search|folder|\bfile\b|host|\bport\b|icon|image|\burl\b|\buri\b|email|version|sha|hash|target|network|mode|\btype\b|command|args|regex|pattern|mask|template|\bxml\b|\byaml\b|\bjson\b)/i.test(key))return false;
  if(/^(repository|web ui|icon|support|project|template|target|type|mode|network)$/i.test(label))return false;
  if(field.dataset.templateRootAttribute)return false;
  if(field.dataset.configAttribute&&!/^description$/i.test(field.dataset.configAttribute))return false;
  if((field.dataset.templateRootIndex!==undefined||field.dataset.templateNewElement)&&!/^(name|overview|description|changes)$/i.test(label))return false;
  return true;
}

function enhanceAIField(field){
  if(!aiFieldAllowed(field))return;
  field.dataset.aiEnhanced='true';
  const control=document.createElement('span');
  control.className='ai-field-control';
  field.parentNode.insertBefore(control,field);
  control.append(field);
  const button=document.createElement('button');
  button.type='button';
  button.className='ai-field-button';
  button.textContent='✦';
  button.title='Generate text with local AI';
  button.setAttribute('aria-label',`Generate ${aiFieldLabel(field)} with local AI`);
  control.append(button);
}

function enhanceAIFields(root=document){
  if(!aiConfig.configured)return;
  root.querySelectorAll('input,textarea').forEach(enhanceAIField);
}

function removeAIFieldControls(root=document){
  root.querySelectorAll('.ai-field-control').forEach(control=>{
    const field=control.querySelector('input,textarea');
    if(field){control.parentNode.insertBefore(field,control);delete field.dataset.aiEnhanced}
    control.remove();
  });
  root.querySelectorAll('.ai-suggestion').forEach(panel=>panel.remove());
}

function aiFieldContext(field){
  const parts=[];
  const page=document.querySelector('.page.active-page h1');
  if(page)parts.push(`Page: ${page.textContent.trim()}`);
  const repo=document.querySelector('#repoName');
  if(repo&&!/no repository/i.test(repo.textContent))parts.push(`Repository: ${repo.textContent.trim()}`);
  const template=document.querySelector('#templateEditorSelect');
  if(template&&template.selectedOptions[0]?.value)parts.push(`Template: ${template.selectedOptions[0].textContent.trim()}`);
  if(typeof templateEditorPath==='string'&&templateEditorPath)parts.push(`Template file: ${templateEditorPath}`);
  const card=field.closest('.template-config-card');
  const setting=card?.querySelector('.template-config-heading b')?.textContent.trim();
  if(setting)parts.push(`Setting: ${setting}`);
  const appName=document.querySelector('#populateForm [name="name"]')?.value.trim();
  if(appName)parts.push(`App name: ${appName}`);
  const image=document.querySelector('#populateForm [name="image"]')?.value.trim();
  if(image)parts.push(`Docker image: ${image}`);
  return parts.join('\n').slice(0,4000);
}

function ensureAISuggestion(field){
  const control=field.closest('.ai-field-control');
  if(!control)return null;
  let panel=control.nextElementSibling;
  if(!panel||!panel.classList.contains('ai-suggestion')){
    panel=document.createElement('div');
    panel.className='ai-suggestion';
    panel.hidden=true;
    panel.innerHTML='<div class="ai-suggestion-head"><span>✦ AI draft</span><button type="button" class="ai-suggestion-close" aria-label="Close AI draft">×</button></div><textarea class="ai-suggestion-text" rows="3" readonly aria-label="AI draft"></textarea><div class="ai-suggestion-actions"><button type="button" class="primary small ai-suggestion-use">Use this text</button><button type="button" class="outline small ai-suggestion-retry">Try again</button><small class="ai-suggestion-status" aria-live="polite"></small></div>';
    control.after(panel);
    panel.querySelector('.ai-suggestion-close').addEventListener('click',()=>{panel.hidden=true;field.focus()});
    panel.querySelector('.ai-suggestion-use').addEventListener('click',()=>useAISuggestion(field,panel));
    panel.querySelector('.ai-suggestion-retry').addEventListener('click',()=>runAIField(field,panel));
  }
  return panel;
}

function useAISuggestion(field,panel){
  const text=panel.querySelector('.ai-suggestion-text').value;
  if(!text)return;
  field.value=text;
  field.dispatchEvent(new Event('input',{bubbles:true}));
  field.dispatchEvent(new Event('change',{bubbles:true}));
  panel.hidden=true;
  field.focus();
  toast('AI text inserted. Review it before saving.');
}

async function runAIField(field,panel){
  const button=field.closest('.ai-field-control')?.querySelector('.ai-field-button');
  const output=panel.querySelector('.ai-suggestion-text');
  const status=panel.querySelector('.ai-suggestion-status');
  const use=panel.querySelector('.ai-suggestion-use');
  panel.hidden=false;
  panel.classList.add('busy');
  use.disabled=true;
  status.textContent='Asking the local model…';
  if(button)button.disabled=true;
  try{
    const label=aiFieldLabel(field);
    const max=field.maxLength>0?Math.min(field.maxLength,4000):(field.tagName==='TEXTAREA'?1800:240);
    const result=await api('/api/ai/generate',{method:'POST',body:JSON.stringify({field:field.name||field.id||label,label,context:aiFieldContext(field),current_value:field.value.slice(0,4000),max_chars:max})});
    output.value=result.text;
    status.textContent=`Draft from ${result.model}. Review it, then use the text.`;
    use.disabled=false;
  }catch(error){
    output.value='';
    status.textContent=error.message;
  }finally{
    panel.classList.remove('busy');
    if(button)button.disabled=false;
  }
}

document.addEventListener('click',event=>{
  const button=event.target.closest('.ai-field-button');
  if(!button)return;
  const field=button.closest('.ai-field-control')?.querySelector('input,textarea');
  if(!field)return;
  event.preventDefault();
  const panel=ensureAISuggestion(field);
  if(panel)runAIField(field,panel);
});

function renderAIModelOptions(models,selected){
  const select=document.querySelector('#aiModel');
  if(!select)return;
  const list=[...new Set([...(models||[]),...(selected?[selected]:[])])];
  select.innerHTML=list.length?list.map(model=>`<option value="${escapeHtml(model)}">${escapeHtml(model)}</option>`).join(''):'<option value="">Check the endpoint to load models</option>';
  if(selected)select.value=selected;
}

function renderAISettings(){
  const badge=document.querySelector('#aiSettingsBadge');
  if(!badge)return;
  badge.className=`pill ${aiConfig.configured?'good':'pending'}`;
  badge.textContent=aiConfig.configured?`CONNECTED · ${aiConfig.model||'AI'}`:'NOT CONNECTED';
  const remove=document.querySelector('#removeAISettings');
  if(remove)remove.hidden=!aiConfig.configured;
  renderAIModelOptions(aiConfig.models,aiConfig.model);
}

async function loadAISettings(){
  const status=document.querySelector('#aiSettingsStatus');
  try{
    const data=await api('/api/settings/ai');
    aiConfig={...aiConfig,...data,models:Array.isArray(data.models)?data.models:[]};
    const base=document.querySelector('#aiBaseUrl');
    if(base&&document.activeElement!==base)base.value=aiConfig.base_url||'';
    const key=document.querySelector('#aiApiKey');
    if(key)key.placeholder=aiConfig.api_key_set?'Saved key — leave blank to keep it':'Leave blank if the endpoint has no key';
    renderAISettings();
    if(status)status.textContent=aiConfig.configured?`Connected to ${aiConfig.base_url} using ${aiConfig.model}.`:'No local AI endpoint connected.';
    if(aiConfig.configured)enhanceAIFields(document);else removeAIFieldControls(document);
  }catch(error){
    if(status)status.textContent=error.message;
  }
}
let aiChecking=false;

async function discoverAIModels(){
  const button=document.querySelector('#aiDiscoverModels');
  const status=document.querySelector('#aiSettingsStatus');
  const base=document.querySelector('#aiBaseUrl');
  const key=document.querySelector('#aiApiKey');
  if(!base||!base.value.trim()){if(status)status.textContent='Enter the endpoint base URL first.';base?.focus();aiChecking=false;return}
  const original=button.textContent;
  aiChecking=true;
  if(status)status.textContent='Asking the endpoint for its model list…';
  try{
    const data=await api('/api/settings/ai/models',{method:'POST',body:JSON.stringify({base_url:base.value.trim(),api_key:key.value.trim()})});
    base.value=data.base_url;
    renderAIModelOptions(data.models);
    if(status)status.textContent=`Connected. Found ${data.models.length} model${data.models.length===1?'':'s'}. Choose one and save.`;
  }catch(error){
    if(status)status.textContent=error.message;
  }finally{
    aiChecking=false;
    button.textContent=original;
  }
}

document.querySelector('#aiDiscoverModels')?.addEventListener('click',event=>{event.preventDefault();discoverAIModels();});
document.querySelector('#aiSettingsForm')?.addEventListener('submit',async event=>{
  event.preventDefault();
  const base=document.querySelector('#aiBaseUrl');
  const key=document.querySelector('#aiApiKey');
  const model=document.querySelector('#aiModel');
  const status=document.querySelector('#aiSettingsStatus');
  const button=event.currentTarget.querySelector('button[type="submit"]');
  if(!base.value.trim()){if(status)status.textContent='Enter the endpoint base URL first.';base.focus();return}
  if(!model.value.trim()){if(status)status.textContent='Check the endpoint first to load models, then choose one.';return}
  button.disabled=true;
  if(status)status.textContent='Checking the endpoint and saving settings…';
  try{
    const data=await api('/api/settings/ai',{method:'POST',body:JSON.stringify({base_url:base.value.trim(),api_key:key.value.trim(),model:model.value})});
    key.value='';
    aiConfig={...aiConfig,...data};
    renderAISettings();
    if(status)status.textContent=`Saved. Connected to ${data.base_url} using ${data.model}.`;
    toast('Local AI assistant connected.');
    await loadAISettings();
  }catch(error){
    if(status)status.textContent=error.message;
    else toast(error.message);
  }finally{
    button.disabled=false;
  }
});
document.querySelector('#removeAISettings')?.addEventListener('click',async()=>{
  if(!confirm('Remove the saved local AI endpoint and API key from this computer?'))return;
  try{
    await api('/api/settings/ai/remove',{method:'POST',body:'{}'});
    aiConfig={configured:false,base_url:'',model:'',models:[],api_key_set:false};
    document.querySelector('#aiBaseUrl').value='';
    document.querySelector('#aiApiKey').value='';
    renderAISettings();
    removeAIFieldControls(document);
    const status=document.querySelector('#aiSettingsStatus');
    if(status)status.textContent='No local AI endpoint connected.';
    toast('Local AI settings removed.');
  }catch(error){toast(error.message)}
});
loadAISettings();

/* Unraid host runtime */
function renderRuntime(){
  const badge=document.querySelector('#runtimeBadge');
  const box=document.querySelector('#runtimeStatus');
  if(!badge||!box)return;
  badge.className=`pill ${runtime.unraid?'good':'pending'}`;
  badge.textContent=runtime.unraid?`UNRAID${runtime.version?' · '+runtime.version:''}`:'WORKSTATION';
  const docker=runtime.docker||{},plugins=runtime.plugins||{},ca=runtime.ca||{},templates=runtime.templates_user||{};
  const row=(label,value,ok)=>`<div class="runtime-row"><span>${escapeHtml(label)}</span><b class="${ok===false?'runtime-bad':ok===true?'runtime-good':''}">${escapeHtml(value)}</b></div>`;
  box.innerHTML=[
    row('Platform',runtime.unraid?`Unraid ${runtime.version||''}`.trim():'This computer (not Unraid)',runtime.unraid),
    row('Docker',docker.available?`${docker.mode||'Docker'} · ${docker.version||'available'}`:`Unavailable · ${docker.mode||'Docker'}`,docker.available),
    row('Plugin manager',plugins.available?`Available · ${plugins.count||0} installed plugin file(s)`:'Not available outside Unraid',plugins.available),
    row('Community Applications',ca.active?'Installed on this Unraid host':'Not detected; using the public CA catalog',ca.active),
    row('Unraid user templates',templates.active?templates.path:'Not available outside Unraid',templates.active),
  ].join('');
  if(runtime.unraid)box.insertAdjacentHTML('beforeend','<p class="runtime-note">CA Workshop is using the Unraid Docker socket and plugin manager. Plugin installs from the CA Store run through Unraid’s own plugin manager after confirmation.</p>');
}
async function loadRuntime(){
  try{
    runtime={...runtime,...await api('/api/runtime')};
    renderRuntime();
    updateUnraidModeUI();
    return runtime;
  }catch(error){
    const box=document.querySelector('#runtimeStatus');
    if(box)box.textContent=error.message;
    return runtime;
  }
}
loadRuntime();
document.querySelector('#browseParent')?.addEventListener('click',async()=>{try{const path=window.prompt('Enter parent folder for clone (e.g. /mnt/cache or /home/user/dev):');if(path){const p=document.querySelector('#bootstrapParent');if(p)p.value=path.trim();}}catch(e){}});
